import { useEffect, useState } from "react";
import axios from "axios";

export default function Perfil() {
  const [usuario, setUsuario] = useState(null);
  const [erro, setErro] = useState("");

  useEffect(() => {
    axios
      .get("http://localhost:3001/usuario")
      .then((res) => setUsuario(res.data))
      .catch((err) => {
        console.error(err);
        setErro("Erro ao carregar o perfil.");
      });
  }, []);

  if (erro) return <div className="alert alert-danger">{erro}</div>;
  if (!usuario) return <p>Carregando perfil...</p>;

  return (
    <div className="container mt-4">
      <h3 className="mb-4">Perfil de Usuário</h3>
      <div className="card" style={{ maxWidth: "500px" }}>
        <img
          src={`http://localhost:3001${usuario.imagem}`}
          className="card-img-top"
          alt="Foto de perfil"
        />
        <div className="card-body">
          <h5 className="card-title">{usuario.nome}</h5>
          <p className="card-text">
            <strong>Idade:</strong> {usuario.idade} <br />
            <strong>Endereço:</strong> {usuario.rua}, {usuario.bairro}, {usuario.estado} <br />
            <strong>Biografia:</strong> {usuario.biografia}
          </p>
        </div>
      </div>
    </div>
  );
}
